    analyzeBatchFiles() {
      // 检查文件数量是否为偶数
      if (this.batchFileList.length % 2 !== 0) {
        // this.$message.warning("上传图片数量为奇数，最后一张图片将不会被处理");
      }

      // 计算能处理的图片对数量
      const pairCount = Math.floor(this.batchFileList.length / 2);

      // 检查图片对数量与选择的患者数量关系
      if (this.selectedPatientIds.length > 0) {
        if (pairCount < this.selectedPatientIds.length) {
          this.$message.warning(`图片对数量(${pairCount})少于患者数量(${this.selectedPatientIds.length})，未选中的患者将不会被处理`);
        } else if (pairCount > this.selectedPatientIds.length) {
          this.$message.warning(`图片对数量(${pairCount})多于患者数量(${this.selectedPatientIds.length})，多余的图片对将不会被处理`);
        }
      }

      // 按顺序配对图片（只处理偶数张）
      this.pairedImages = [];
      const evenCount = Math.floor(this.batchFileList.length / 2) * 2;
      for (let i = 0; i < evenCount; i += 2) {
        this.pairedImages.push({
          leftEye: this.batchFileList[i],
          rightEye: this.batchFileList[i + 1]
        });
      }

      // 记录未配对的图片
      this.unpairedImages = this.batchFileList.length % 2 !== 0 ? [this.batchFileList[this.batchFileList.length - 1]] : [];
    },
    async processBatchImages() {
      if (this.selectedPatientIds.length === 0) {
        this.$message.warning("请先选择患者");
        return;
      }

      // 获取有效的文件夹（至少包含2张图片）
      const validFolders = this.patientFolders.filter(folder => folder.files.length >= 2);
      if (validFolders.length === 0) {
        this.$message.warning("请上传至少一个包含足够图像的文件夹");
        return;
      }

      // 验证患者数量和文件夹数量是否匹配
      if (this.selectedPatientIds.length < validFolders.length) {
        this.$message.warning(`选择的患者数量(${this.selectedPatientIds.length})少于有效的文件夹数量(${validFolders.length})`);
        return;
      }

      // 开始处理
      this.processingMode = "batch";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      this.processedCount = 0;
      this.totalProcessCount = validFolders.length;
      this.taskQueue = [];
      this.currentTaskIndex = 0;
      this.uploadedFolderPaths = [];
      try {
        // 准备上传文件夹
        for (let i = 0; i < validFolders.length; i++) {
          const patientId = this.selectedPatientIds[i];
          const folder = validFolders[i];

          // 添加到任务队列
          this.taskQueue.push({
            id: patientId,
            name: folder.name,
            status: i === 0 ? "processing" : "waiting"
          });
        }

        // 所有图片路径
        const allImagePaths = [];

        // 逐个上传文件夹
        for (let i = 0; i < validFolders.length; i++) {
          this.currentTaskIndex = i;
          this.taskQueue[i].status = "processing";

          // 更新进度
          this.processedCount = i;
          this.processingPercentage = Math.floor(i / this.totalProcessCount * 50); // 上传占总进度的50%

          // 等待一小段时间以便UI更新
          await new Promise(resolve => setTimeout(resolve, 100));
          const folder = validFolders[i];
          const folderPaths = [];

          // 为每个文件创建单独的请求
          for (let j = 0; j < folder.files.length; j++) {
            const file = folder.files[j];
            const formData = new FormData();
            formData.append("folder", file); // 根据API文档，参数名是folder

            try {
              // 上传文件
              const uploadResponse = await request({
                method: "post",
                url: "/common/upload/folder",
                data: formData,
                headers: {
                  "Content-Type": "multipart/form-data"
                }
              });
              if (uploadResponse.code === 1 || uploadResponse.code === 200) {
                // 保存返回的文件路径
                folderPaths.push(uploadResponse.data);
              } else {
                throw new Error(`文件 ${file.name} 上传失败: ${uploadResponse.msg}`);
              }
            } catch (error) {
              console.error(`上传文件 ${file.name} 失败:`, error);
              this.$message.warning(`文件 ${file.name} 上传失败，将继续尝试上传其他文件`);
            }
          }

          // 如果成功上传了该文件夹的所有文件
          if (folderPaths.length > 0) {
            this.uploadedFolderPaths.push(folderPaths);
            allImagePaths.push(...folderPaths);
            this.taskQueue[i].status = "completed";
          } else {
            // 如果该文件夹的所有文件都上传失败
            this.taskQueue[i].status = "failed";
            this.$message.error(`文件夹 ${folder.name} 所有文件上传失败`);
          }
        }

        // 如果没有成功上传任何文件
        if (this.uploadedFolderPaths.length === 0) {
          throw new Error("所有文件上传失败");
        }

        // 更新进度到80%，表示上传完成，开始诊断
        this.processingPercentage = 80;

        // 发送批量诊断请求
        // 获取要诊断的患者ID（仅包括成功上传文件的患者）
        const selectedPatients = validFolders.filter((_, index) => this.taskQueue[index].status === "completed").map((_, index) => this.selectedPatientIds[index]);
        if (selectedPatients.length > 0) {
          const doctorId = localStorage.getItem("doctorId");

          // 构建诊断请求数据，严格按照API文档格式
          const diagnosisData = {
            patientIds: selectedPatients,
            doctorId: parseInt(doctorId),
            imagePaths: allImagePaths
          };
          console.log("批量诊断请求数据:", diagnosisData);

          // 发送诊断请求
          const diagnosisResponse = await request({
            method: "post",
            url: "/diagnose/batch",
            data: diagnosisData,
            headers: {
              "Content-Type": "application/json"
            }
          });
          if (diagnosisResponse.code === 1 || diagnosisResponse.code === 200) {
            this.processBatchResults(diagnosisResponse.data);
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.showResults = true;
            }, 500);
          } else {
            throw new Error(diagnosisResponse.msg || "批量诊断失败");
          }
        } else {
          throw new Error("没有成功上传文件的患者，无法进行诊断");
        }
      } catch (error) {
        console.error("批量处理错误:", error);
        this.$message.error(error.message || "批量处理失败，请稍后重试");
        this.processingDialogVisible = false;
      }
    },
    processBatchResults(results) {
      // 确保 results 是数组
      if (!Array.isArray(results)) {
        console.error("Invalid results format:", results);
        this.$message.error("诊断结果格式错误");
        return;
      }
      this.batchResults = results.map(result => ({
        id: result.patientId,
        leftEye: {
          diagnosis: result.leftResult,
          confidence: Math.max(...(result.diseaseLeft?.probabilities || [0])) * 100,
          probabilities: result.diseaseLeft?.probabilities || []
        },
        rightEye: {
          diagnosis: result.rightResult,
          confidence: Math.max(...(result.diseaseRight?.probabilities || [0])) * 100,
          probabilities: result.diseaseRight?.probabilities || []
        },
        finalDiagnosis: result.finalResult,
        suggestion: this.generateSuggestion(this.diseaseCategories.indexOf(result.leftResult), this.diseaseCategories.indexOf(result.rightResult))
      }));

      // 更新患者诊断信息
      this.batchResults.forEach(result => {
        const patientIndex = this.patientList.findIndex(p => p.id === result.id);
        if (patientIndex !== -1) {
          const patient = this.patientList[patientIndex];
          patient.leftEyeDiagnosis = result.leftEye.diagnosis;
          patient.rightEyeDiagnosis = result.rightEye.diagnosis;
          patient.finalDiagnosis = result.finalDiagnosis;
          patient.leftEyeConfidence = result.leftEye.confidence;
          patient.rightEyeConfidence = result.rightEye.confidence;
          patient.processTime = new Date().toLocaleString();

          // 更新患者列表
          this.patientList[patientIndex] = {
            ...patient
          };
        }
      });

      // 添加到历史记录
      this.batchResults.forEach(result => {
        this.addToHistory({
          id: result.id,
          patientId: result.id,
          leftEye: result.leftEye.diagnosis,
          rightEye: result.rightEye.diagnosis,
          comprehensiveDiagnosis: result.finalDiagnosis,
          diagnosisTime: new Date().toLocaleString()
        });
      });
    },
    // 处理图像
    async processSingleImages() {
      if (!this.selectedPatientId) {
        this.$message.warning("请先选择患者");
        return;
      }
      this.processingMode = "single";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      try {
        // 创建FormData对象
        const leftFormData = new FormData();
        const rightFormData = new FormData();

        // 添加文件到FormData
        leftFormData.append("file", this.leftEyeFile);
        rightFormData.append("file", this.rightEyeFile);

        // 上传左眼图像
        const leftResponse = await request({
          method: "post",
          url: "/common/upload",
          data: leftFormData,
          headers: {
            "Content-Type": "multipart/form-data"
          }
        });

        // 上传右眼图像
        const rightResponse = await request({
          method: "post",
          url: "/common/upload",
          data: rightFormData,
          headers: {
            "Content-Type": "multipart/form-data"
          }
        });
        if (leftResponse.code === 1 && rightResponse.code === 1) {
          // 获取上传后的文件路径
          const leftImagePath = leftResponse.data;
          const rightImagePath = rightResponse.data;

          // 调用诊断API
          const doctorId = localStorage.getItem("doctorId");
          const diagnosisResponse = await request({
            method: "post",
            url: "/diagnose",
            data: {
              patientId: this.selectedPatientId,
              doctorId: parseInt(doctorId),
              imagePaths: [leftImagePath, rightImagePath]
            }
          });
          if (diagnosisResponse.code === 1) {
            const result = diagnosisResponse.data;

            // 更新诊断结果
            this.singleResult = {
              leftEye: {
                diagnosis: this.getDiagnosisFromLabels(result.diseaseLeft.labels),
                confidence: Math.max(...result.diseaseLeft.probabilities) * 100,
                probabilities: result.diseaseLeft.probabilities
              },
              rightEye: {
                diagnosis: this.getDiagnosisFromLabels(result.diseaseRight.labels),
                confidence: Math.max(...result.diseaseRight.probabilities) * 100,
                probabilities: result.diseaseRight.probabilities
              },
              finalDiagnosis: result.finalResult,
              suggestion: this.generateSuggestion(this.diseaseCategories.indexOf(this.getDiagnosisFromLabels(result.diseaseLeft.labels)), this.diseaseCategories.indexOf(this.getDiagnosisFromLabels(result.diseaseRight.labels)))
            };

            // 更新患者诊断信息
            const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
            if (patientIndex !== -1) {
              const patient = this.patientList[patientIndex];
              patient.leftEyeDiagnosis = result.leftResult; // 使用API返回的左眼结果
              patient.rightEyeDiagnosis = result.rightResult; // 使用API返回的右眼结果
              patient.finalDiagnosis = result.finalResult; // 使用API返回的最终结果
              patient.leftEyeConfidence = Math.max(...result.diseaseLeft.probabilities) * 100;
              patient.rightEyeConfidence = Math.max(...result.diseaseRight.probabilities) * 100;
              patient.processTime = new Date().toLocaleString();

              // this.$set(this.patientList, patientIndex, patient);
              // Use direct assignment for Vue 3 reactivity
              this.patientList[patientIndex] = patient;
            }

            // 更新进度并显示结果
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.updatePatientDiagnosis();
              this.showResults = true;

              // 添加到历史记录
              this.addToHistory(this.singleResult);

              // 渲染图表
              this.$nextTick(() => {
                this.renderEyeChart("leftEyeChart", this.singleResult.leftEye.probabilities);
                this.renderEyeChart("rightEyeChart", this.singleResult.rightEye.probabilities);
                this.renderComparisonChart(this.singleResult.leftEye.probabilities, this.singleResult.rightEye.probabilities);
              });
            }, 500);
          } else {
            throw new Error(diagnosisResponse.msg || "诊断失败");
          }
        } else {
          throw new Error("文件上传失败");
        }
      } catch (error) {
        console.error("处理图像错误:", error);
        this.$message.error(error.message || "图像处理失败，请稍后重试");
        this.processingDialogVisible = false;
      }
    },
    // 根据标签数组获取诊断结果
    getDiagnosisFromLabels(labels) {
      // 根据返回的标签数组中最可能的标签确定诊断结果
      if (labels && labels.length > 0) {
        const label = labels[0]; // 取第一个最可能的标签
        switch (label) {
          case "A":
            return "糖尿病视网膜病变";
          case "G":
            return "青光眼";
          case "C":
            return "白内障";
          case "H":
            return "高血压视网膜病变";
          case "M":
            return "近视";
          case "O":
            return "其他异常";
          case "N":
            return "正常";
          default:
            return "未知";
        }
      }
      return "未知";
    },
    updatePatientDiagnosis() {
      // 更新患者诊断信息
      if (this.selectedPatientId && this.singleResult) {
        const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
        if (patientIndex !== -1) {
          const patient = this.patientList[patientIndex];
          const now = new Date();
          patient.leftEyeDiagnosis = this.singleResult.leftEye.diagnosis;
          patient.leftEyeConfidence = this.singleResult.leftEye.confidence;
          patient.rightEyeDiagnosis = this.singleResult.rightEye.diagnosis;
          patient.rightEyeConfidence = this.singleResult.rightEye.confidence;
          patient.finalDiagnosis = this.singleResult.finalDiagnosis;
          patient.processTime = now.toLocaleString();

          // this.$set(this.patientList, patientIndex, patient);
          // Use direct assignment for Vue 3 reactivity
          this.patientList[patientIndex] = patient;
        }
      }
    },
