    // 生成建议
    generateSuggestion(leftIndex, rightIndex) {
      // 根据诊断结果生成建议
      const suggestions = {
        0: "建议进行血糖控制，定期复查眼底，必要时考虑激光或抗VEGF治疗。",
        1: "建议测量眼压，进行视野检查，必要时使用降眼压药物。",
        2: "建议进行视力矫正，必要时考虑白内障手术。",
        3: "建议定期监测黄斑区变化，必要时考虑抗VEGF治疗。",
