      this.fetchHistoryRecords();
    },
    // 计算文件大小的格式化方法
    formatFileSize(row, column, cellValue) {
      const size = row.size;
      if (size < 1024) {
        return size + " B";
      } else if (size < 1024 * 1024) {
        return (size / 1024).toFixed(1) + " KB";
      } else {
        return (size / (1024 * 1024)).toFixed(1) + " MB";
      }
    },
    // 判断文件是否已配对
    isFilePaired(file) {
      return file.isPaired === true;
    },
    // 保存患者列表到 localStorage
    savePatientListToLocalStorage() {
      localStorage.setItem("patientList", JSON.stringify(this.patientList));
    },
    // 从 localStorage 读取患者列表
    loadPatientListFromLocalStorage() {
      const savedPatientList = localStorage.getItem("patientList");
      if (savedPatientList) {
        this.patientList = JSON.parse(savedPatientList);
        return true;
      }
      return false;
    },
    formatTime(timeInput) {
      if (!timeInput) return "";
      try {
        let date;
        // 判断传入的是否为数组
        if (Array.isArray(timeInput)) {
          // 假设数组顺序为 [year, month, day, hour, minute, second]
          const [year, month, day, hour, minute, second] = timeInput;
          // 注意：month 需要减1，因为 JavaScript 中月份从0开始
          date = new Date(year, month - 1, day, hour, minute, second);
        } else {
          date = new Date(timeInput);
        }
        if (isNaN(date.getTime())) return timeInput; // 如果日期无效，则返回原始输入

        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");
        const seconds = String(date.getSeconds()).padStart(2, "0");
        return `${year}/${month}/${day} ${hours}:${minutes}:${seconds}`;
      } catch (error) {
        console.error("Error formatting time:", error);
        return timeInput;
      }
    },
    // 处理文件夹上传
    processFolderUpload(file, fileList) {
      // 提取文件夹名称
      const folderPath = file.raw.webkitRelativePath;
      const folderName = folderPath.split("/")[0];

      // 检查该文件夹是否已经在列表中
      const existingFolder = this.patientFolders.find(folder => folder.name === folderName);
      if (!existingFolder) {
        // 添加新文件夹
        this.patientFolders.push({
          name: folderName,
          files: [file.raw],
          element: file
        });
      } else {
        // 向现有文件夹添加文件
        existingFolder.files.push(file.raw);
      }

      // 显示当前上传的文件夹情况
      this.updateFolderStatus();
    },
    // 更新文件夹状态显示
    updateFolderStatus() {
      // 清空之前的文件列表，使用文件夹列表代替
      this.batchFileList = this.patientFolders.map(folder => {
        return {
          name: folder.name,
          size: folder.files.reduce((total, file) => total + file.size, 0),
          raw: folder.element?.raw,
          // 保留一个文件的引用
          status: folder.files.length >= 2 ? "success" : "warning",
          isPaired: folder.files.length >= 2,
          fileCount: folder.files.length
        };
      });

      // 更新配对信息
      this.pairedImages = this.patientFolders.filter(folder => folder.files.length >= 2).map(folder => {
        return {
          folderName: folder.name,
          leftEye: folder.files[0],
          rightEye: folder.files[1]
        };
      });
      this.unpairedImages = this.patientFolders.filter(folder => folder.files.length < 2).flatMap(folder => folder.files);
    },
    // 点击浏览文件夹按钮
    browseFolders() {
      const input = document.createElement("input");
      input.type = "file";
      input.webkitdirectory = true;
      input.multiple = true;
      input.directory = true; // 支持多文件夹选择（非标准属性，部分浏览器支持）

      input.onchange = e => {
        const files = Array.from(e.target.files);
        if (files.length === 0) return;

        // 提示用户正在处理文件
        this.$message.info(`正在处理 ${files.length} 个文件，请稍候...`);

        // 按文件夹分组文件
        const folderMap = new Map();
        files.forEach(file => {
          const path = file.webkitRelativePath;
          const parts = path.split("/");

          // 检查是否有多级目录
          if (parts.length < 2) return; // 跳过没有路径的文件

          const folderName = parts[0]; // 顶级文件夹名称

          if (!folderMap.has(folderName)) {
            folderMap.set(folderName, []);
          }
          folderMap.get(folderName).push(file);
        });

        // 处理之前是否已有文件夹
        const existingFolders = new Set(this.patientFolders.map(f => f.name));
        let newFoldersCount = 0;

        // 将分组后的文件夹添加到列表
        folderMap.forEach((files, folderName) => {
          // 检查是否已存在同名文件夹
          if (existingFolders.has(folderName)) {
            // 更新现有文件夹内容
            const existingFolder = this.patientFolders.find(f => f.name === folderName);
            if (existingFolder) {
              existingFolder.files = files;
              existingFolder.element = {
                raw: files[0]
              }; // 更新代表文件
            }
          } else {
            // 添加新文件夹
            this.patientFolders.push({
              name: folderName,
              files: files,
              element: {
                raw: files[0]
              } // 保存第一个文件作为代表
            });
            newFoldersCount++;
          }
        });

        // 更新界面显示
        this.updateFolderStatus();

        // 提示用户上传结果
        if (newFoldersCount > 0) {
          this.$message.success(`成功添加 ${newFoldersCount} 个新文件夹`);
        } else {
          this.$message.warning("没有添加新文件夹，可能是文件夹名称已存在");
        }
      };
      input.click();
    }
  },
